// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;
    Log logHelper;

    function setUp() public {
        logHelper = new Log();
        c = new PrivateBank(address(logHelper));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount >= c.MinDeposit());
        vm.deal(actor, amount);

        vm.prank(actor);
        c.Deposit{value: amount}();

        (
            address sender,
            string memory data,
            uint256 val,

        ) = logHelper.History(0);

        assertTrue(val == amount);
    }
}
